function ensureCompletedSubmission(course, assignment){
  if(!assignment?.completed) return;
  const key=`${course.id}:${assignment.id}`;
  if(!state.submissions[key]?.submitted){
    state.submissions[key]={submitted:true,answers:assignment.sampleAnswers||[],fileName:'',submittedAt:assignment.submittedAt||'Previously submitted',score:assignment.score??null,feedback:assignment.feedback||'Graded in this fictional simulation.'};
  }
}

function addIfMissing(arr, item){if(!arr.some(x=>x.id===item.id)) arr.push(item);}
function upsertLecture(course,id,lecture){course.lectures=course.lectures||{};course.lectures[id]=lecture;}
function moduleHas(course,title){return course.modules.some(m=>m.title===title);}

