const engr=BASE_COURSES.find(c=>c.id==='engr10');
upsertLecture(engr,'engr-l1b',{
  title:'Lecture 1B · Engineering Ethics, Risk & Professional Judgment',week:'Week 1 · Aug 27',duration:'42 min',
  objectives:['Distinguish technical risk from ethical responsibility','Explain why uncertainty must be communicated','Identify conflicts among safety, cost, schedule, and public welfare'],
  sections:[
    ['Engineering decisions affect people','Technical work is never isolated from consequences. Even a small design choice can affect users, maintenance staff, neighbors, budgets, emergency access, or future repair crews.'],
    ['Risk is not zero','Engineers manage risk by identifying hazards, estimating likelihood and consequence, reducing uncertainty, and documenting assumptions. “Safe” does not mean “nothing can ever go wrong.”'],
    ['Communicate uncertainty','If a cost, material property, demand forecast, or site condition is uncertain, state that uncertainty. A precise-looking number can mislead when its inputs are weak.'],
    ['Professional judgment','Codes and calculations set important boundaries, but judgment is still needed when requirements conflict or information is incomplete. The reasoning should be transparent and reviewable.'],
    ['Mini case','A temporary repair is cheaper and faster, but inspection data is incomplete. A responsible recommendation explains what is known, what is uncertain, what could happen if the assumption is wrong, and what additional information would reduce uncertainty.']
  ],
  keyTerms:['risk','uncertainty','public welfare','professional judgment','assumption','hazard'],
  check:[
    {q:'What is the best response to an uncertain cost estimate?',options:['Hide the uncertainty','Report the estimate and explain the uncertainty/assumptions','Round it to an exact dollar','Ignore it if the schedule is tight'],answer:1},
    {q:'Engineering ethics is most connected to…',options:['Only avoiding lawsuits','How technical decisions affect people and public welfare','Choosing the cheapest option','Making drawings look professional'],answer:1}
  ]
});
upsertLecture(engr,'engr-l2b',{
  title:'Workshop · Decision Matrices & Sensitivity Checks',week:'Week 2 · Sep 3',duration:'38 min',
  objectives:['Build a weighted scoring model','Check arithmetic and consistency','Test how weight changes affect a recommendation'],
  sections:[
    ['Step 1 · Criteria','Use criteria that actually distinguish alternatives. “Good design” is too broad; “minimum clear width,” “annual maintenance hours,” or “estimated installed cost” are easier to evaluate.'],
    ['Step 2 · Weights','Weights express relative importance. They should total 100%. A 30% safety/accessibility criterion should influence the outcome more than a 10% aesthetic preference.'],
    ['Step 3 · Scores','Use the same scoring scale for every alternative and define what the scale means. Avoid giving a preferred concept a special scale.'],
    ['Step 4 · Sensitivity','Change the most uncertain or influential weights. If the winner changes easily, report that sensitivity instead of pretending the decision is robust.']
  ],
  keyTerms:['weight','normalized score','sensitivity','robust decision'],
  check:[{q:'A sensitivity check is most useful when…',options:['There is only one concept','A small assumption change may alter the ranking','All weights are zero','The decision has already been announced'],answer:1}]
});
upsertLecture(engr,'engr-l3b',{
  title:'Lecture 3B · Moments, Torque & Choosing a Pivot',week:'Week 3 · Sep 10',duration:'51 min',
  objectives:['Compute a planar moment from force and lever arm','Use a sign convention consistently','Choose a pivot that simplifies an equilibrium equation'],
  sections:[
    ['Moment idea','A force can cause translation and rotation. In simple 2D statics, moment magnitude is force times perpendicular distance to the line of action.'],
    ['Sign convention','A common convention treats counterclockwise moments as positive and clockwise moments as negative. Any convention works if used consistently.'],
    ['Choosing the pivot','Taking moments about a support can eliminate unknown reaction components that pass through that point. This often turns several unknowns into one equation.'],
    ['Worked example','A 10-ft beam has a 900-lb downward load 4 ft from support A. Taking moments about A: By(10) − 900(4)=0, giving By=360 lb. Then Ay=540 lb from vertical equilibrium.'],
    ['Reasonableness','The reaction nearer the point load should be larger. If the arithmetic gives the opposite result, check distances and signs.']
  ],
  keyTerms:['moment','torque','lever arm','pivot','clockwise','counterclockwise'],
  check:[
    {q:'A 100-lb force acts 3 ft perpendicular to a pivot. Moment magnitude is:',options:['33.3 lb-ft','100 lb-ft','300 lb-ft','3 lb-ft'],answer:2},
    {q:'Why take moments about a support?',options:['To remove gravity','To eliminate reaction forces whose lines of action pass through the pivot','To make all moments positive','To avoid drawing a free-body diagram'],answer:1}
  ]
});
upsertLecture(engr,'engr-l4',{
  title:'Preview Lecture · Trusses & Structural Systems',week:'Week 4 · Sep 15',duration:'58 min',
  objectives:['Recognize ideal truss assumptions','Describe two-force members','Connect member forces to a larger structural load path'],
  sections:[
    ['Why trusses work','Triangulated systems create stable geometry and allow loads to be carried through axial tension/compression in idealized members.'],
    ['Ideal model','Introductory truss analysis typically assumes pin-connected joints, loads applied at joints, and straight two-force members.'],
    ['Member force','A two-force member carries equal and opposite forces along its axis. The member is classified as being in tension or compression.'],
    ['Whole-system thinking','A truss still needs supports and foundations. Member forces are only one part of the overall load path.']
  ],keyTerms:['truss','two-force member','tension','compression','joint'],
  check:[{q:'In an ideal introductory truss, external loads are usually applied at:',options:['Member midpoints','Joints','Anywhere along every member','The foundation only'],answer:1}]
});

