upsertLecture(ewrt,'ewrt-l1',{title:'Mini Lecture · Active Reading & Annotation',week:'Week 1 · Aug 25',duration:'34 min',objectives:['Annotate claims and evidence','Write useful margin questions','Distinguish summary from analysis'],sections:[['Read with a purpose','Before reading, identify the task: summarize, analyze evidence, compare claims, or prepare for discussion.'],['Useful annotations','Mark claims, evidence, definitions, patterns, questions, and connections. Highlighting everything is not annotation.'],['From note to response','A strong reading response moves from what the author says to how the author supports it and why that support matters.']],keyTerms:['claim','evidence','annotation','analysis'],check:[{q:'Which annotation is most analytical?',options:['“Important”','“This example supports the claim because…”','A yellow highlight','Copying the sentence'],answer:1}]});
upsertLecture(ewrt,'ewrt-l2',{title:'Mini Lecture · Thesis, Evidence & Paragraph Logic',week:'Week 2 · Sep 1',duration:'41 min',objectives:['Write a focused arguable thesis','Select evidence with a clear purpose','Build paragraph logic'],sections:[['Thesis','A thesis makes a focused arguable claim, not just a topic announcement.'],['Evidence','Evidence matters only when the writer explains how it supports the claim.'],['Paragraph logic','Topic sentence → evidence/context → analysis → connection. The analysis is where the writer explains significance instead of merely dropping a quote or fact.']],keyTerms:['thesis','topic sentence','evidence','analysis'],check:[{q:'What usually belongs after evidence?',options:['A new unrelated topic','Analysis explaining why the evidence matters','The title again','Nothing'],answer:1}]});
upsertLecture(ewrt,'ewrt-l3',{title:'Workshop Lecture · Drafting, Reverse Outlining & Revision',week:'Week 3 · Sep 8',duration:'46 min',objectives:['Separate drafting from editing','Use reverse outlining to test organization','Revise at paragraph and sentence levels'],sections:[['Draft first','A first draft is a thinking tool. Trying to perfect every sentence too early can make it harder to discover the argument.'],['Reverse outline','After drafting, write the purpose of each paragraph in the margin. If several paragraphs do the same job or a paragraph has no clear job, reorganize.'],['Revision layers','Start with thesis and structure, then paragraph logic and evidence, then sentence clarity, then proofreading.']],keyTerms:['draft','revision','reverse outline','coherence'],check:[{q:'A reverse outline is created:',options:['Before reading','From the finished or partial draft to inspect paragraph purpose','Only from the assignment prompt','By alphabetizing sentences'],answer:1}]});
addIfMissing(ewrt.assignments,{id:'ewrt-annot',title:'Annotation Check · Claim/Evidence Map',due:'Aug 27 at 11:59 PM',points:12,group:'Reading',kind:'worksheet',completed:true,score:12,submittedAt:'Aug 27 at 8:22 PM',feedback:'Strong distinction between claim and evidence.',instructions:'Map one reading into a main claim, two supporting reasons, and one example of evidence.',questions:[{type:'textarea',q:'Main claim:'},{type:'textarea',q:'Reason 1 + evidence:'},{type:'textarea',q:'Reason 2 + evidence:'}],sampleAnswers:['Public-space design shapes who feels welcome and how long people remain in a place.','Accessibility affects who can use the space; the reading describes how path width and seating layout influence mobility.','Comfort affects duration of use; shade, seating orientation, and noise are used as examples.']});
