ewrt.discussions.push({id:'ewrt-disc3',title:'Week 3 Workshop Board · One Paragraph, One Question',due:'Sep 10 at 11:59 PM',points:10,status:'open',score:null,prompt:'Post one paragraph from your draft (or a short summary of it) and ask one specific revision question. Reply to at least one classmate with feedback focused on thesis, evidence, analysis, or organization.',posts:[
  {name:'Avery Kim',time:'Sep 8 · 12:05 PM',text:'My paragraph argues that shade is an accessibility issue because heat exposure affects who can comfortably use an outdoor space. My question: does that belong before or after my paragraph on circulation?',replies:[{name:'Sofia Reyes',time:'Sep 8 · 12:44 PM',text:'I would put circulation first because it establishes physical access, then shade as the next layer of usable access/comfort.'}]},
  {name:'Noah Brooks',time:'Sep 8 · 2:18 PM',text:'I have evidence about benches being removed to discourage loitering, but my analysis feels repetitive. How can I explain the significance without just saying it makes the space less welcoming?',replies:[{name:'Leah Tran',time:'Sep 8 · 2:47 PM',text:'Maybe focus on who gets excluded and connect the design choice to the policy goal. That gives the example a consequence instead of repeating the description.'},{name:'Jordan Smith',time:'Sep 8 · 3:06 PM',text:'You could also compare the intended goal with an unintended effect.'}]}
]});
