const construction={
  id:'const20',code:'CONST 20',title:'Construction Methods & Materials',instructor:'Prof. Elena Morales',room:'Hybrid · Campus Lab B-14 / Zoom-style sessions (Demo)',schedule:'Wednesday · 6:00–8:30 PM · Hybrid',units:4,color:'#9a6536',grade:94,modality:'Hybrid + Online Labs',week:'Week 3',
  description:'A fictional hands-on introduction to construction drawings, site safety, concrete, wood framing, building envelopes, quantity takeoffs, estimating, sequencing, and basic coordination. Built entirely as an unofficial learning simulation.',
  gradeGroups:[['Plan Reading',20,96],['Labs & Takeoffs',30,93],['Safety',15,95],['Discussions',10,100],['Projects',20,92],['Participation',5,100]],
  lectures:{},assignments:[],discussions:[],zoomMeetings:[],modules:[]
};
upsertLecture(construction,'const-l1',{title:'Lecture 1 · How a Set of Construction Drawings Works',week:'Week 1 · Aug 26',duration:'64 min',objectives:['Navigate plans, elevations, sections, details, and schedules','Use drawing references and scales','Identify where to look when information appears to conflict'],sections:[['Drawing set hierarchy','A drawing set is a coordinated information system. Plans show horizontal organization, elevations show vertical faces, sections cut through assemblies, details enlarge connections, and schedules collect repeated information.'],['General notes and legends','Read general notes and symbol legends before measuring. A dimension or specification note can override an assumption you might make from a picture alone.'],['References','Section/elevation/detail callouts connect one sheet to another. Following references is a core construction-reading skill.'],['Scale','Do not measure from an unverified PDF screenshot. Use written dimensions first; use drawing scale only when the document is known to be printed or displayed at the intended scale.'],['Coordination mindset','If architectural, structural, and MEP information conflict, document the conflict and seek clarification instead of inventing a field solution.']],keyTerms:['plan','elevation','section','detail','schedule','legend','scale','RFI'],check:[{q:'Where is the most detailed view of a connection usually found?',options:['A detail','The cover sheet','The title block only','The north arrow'],answer:0},{q:'If two drawings conflict, the safest student workflow is:',options:['Guess','Document the conflict and seek clarification','Average the two dimensions','Ignore one sheet'],answer:1}]});
upsertLecture(construction,'const-l1b',{title:'Lecture 1B · Construction Safety & Hazard Recognition',week:'Week 1 · Aug 28',duration:'48 min',objectives:['Recognize common construction hazards','Apply the hierarchy of controls conceptually','Explain why planning and training matter before work begins'],sections:[['Hazard recognition','Introductory site safety starts by recognizing exposure: falls, struck-by hazards, electrical hazards, caught-in/between hazards, silica/dust, unstable excavations, moving equipment, and poor housekeeping.'],['Plan before exposure','The best time to control a hazard is before the task begins. Work sequencing, access, equipment selection, barricades, and training should be considered in planning.'],['Controls','Eliminate or reduce the hazard when possible before relying only on personal protective equipment. PPE is important, but it is not a substitute for removing a preventable hazard.'],['Stop and clarify','A worker should not improvise around an unfamiliar hazard. In real work, site-specific training, supervision, company procedures, and applicable regulations control the task.']],keyTerms:['hazard','exposure','PPE','fall protection','housekeeping','competent person'],check:[{q:'Which is generally stronger hazard control than PPE alone?',options:['Eliminating the hazard','Ignoring the hazard','Working faster','Removing warning signs'],answer:0}]});
upsertLecture(construction,'const-l2',{title:'Lecture 2 · Concrete, Reinforcement & Foundations',week:'Week 2 · Sep 2',duration:'69 min',objectives:['Explain basic concrete ingredients and curing','Describe why steel reinforcement is added','Calculate simple concrete quantities','Recognize basic foundation moisture-control layers'],sections:[['Concrete is a composite','Concrete combines cementitious binder, water, fine aggregate, coarse aggregate, and often admixtures. Workability, water content, curing, and placement affect performance.'],['Compression vs tension','Concrete is strong in compression but relatively weak in tension. Reinforcing steel is placed where tensile demand is expected and where crack control/continuity are needed.'],['Quantity','Concrete volume is length × width × thickness. Convert cubic feet to cubic yards by dividing by 27. Add appropriate waste only when the estimating assumption calls for it.'],['Curing','Hydration continues after placement. Protecting moisture and temperature during curing helps concrete develop the intended properties.'],['Foundation moisture','Foundations must manage bulk water, capillary moisture, and drainage. Waterproofing/damp-proofing, drainage layers, grading, vapor control, and capillary breaks work as a system.']],keyTerms:['cement','aggregate','water-cement ratio','reinforcement','rebar','curing','cubic yard','capillary break'],check:[{q:'Why is reinforcing steel commonly used with concrete?',options:['Concrete has relatively low tensile strength','Concrete cannot carry compression','Steel prevents all cracking','Concrete contains no aggregate'],answer:0},{q:'27 cubic feet equals:',options:['1 cubic yard','3 cubic yards','9 cubic yards','27 cubic yards'],answer:0}]});
upsertLecture(construction,'const-l2b',{title:'Workshop · Quantity Takeoff & Estimate Basics',week:'Week 2 · Sep 4',duration:'53 min',objectives:['Separate quantity takeoff from estimating','Choose appropriate units','Build a simple line-item cost extension'],sections:[['Takeoff first','Quantity takeoff answers “how much?”—counts, lengths, areas, volumes, and assemblies measured from the documents.'],['Estimate second','Estimating applies material, labor, equipment, subcontract, overhead, and markup assumptions to quantities. A takeoff is the measurable basis; it is not the complete price.'],['Units matter','Concrete may be cubic yards, flooring square feet, baseboard linear feet, doors each, and rebar pounds. Use the unit that matches the work and pricing basis.'],['Extension','Quantity × unit cost = line-item direct cost. Then other cost categories or markups are added according to the estimate structure.'],['Scope gaps','A neat spreadsheet can still be wrong if scope is missing. Estimators cross-check drawings, schedules, specifications, alternates, and addenda.']],keyTerms:['takeoff','estimate','unit cost','extension','direct cost','scope'],check:[{q:'A quantity takeoff primarily determines:',options:['How much work/material is shown','Final contract terms','Only labor rates','Profit percentage'],answer:0}]});
upsertLecture(construction,'const-l3',{title:'Lecture 3 · Wood Framing, Load Transfer & Openings',week:'Week 3 · Sep 9',duration:'71 min',objectives:['Identify basic wood-framing members','Trace gravity loads through framing','Explain why headers and connections matter around openings'],sections:[['Wall framing vocabulary','Typical light-frame walls include plates, studs, headers, jack/trimmer studs, king studs, blocking, and sheathing. Exact assemblies vary by design.'],['Floor/roof framing','Joists, rafters, trusses, beams, and bearing walls transfer loads through connected components. Member spacing and span affect demand and constructability.'],['Openings','Door and window openings interrupt regularly spaced studs. Headers and supporting studs redirect load around the opening in bearing conditions.'],['Sheathing and connections','Sheathing does more than close the wall; depending on the designed system it can contribute to lateral load resistance. Fastener patterns and connections are part of the load path.'],['Coordination','Framing must coordinate with plumbing, HVAC, electrical, windows, doors, insulation, fire blocking, and finishes. Cutting or drilling structural members without approved details can create problems.']],keyTerms:['stud','plate','header','joist','rafter','truss','sheathing','bearing wall'],check:[{q:'A header over a bearing-wall opening primarily helps:',options:['Redirect load around the opening','Make paint dry faster','Replace all studs in the wall','Waterproof the roof'],answer:0}]});
upsertLecture(construction,'const-l3b',{title:'Lecture 3B · Building Envelope · Water, Air & Heat Control',week:'Week 3 · Sep 11',duration:'56 min',objectives:['Describe water, air, vapor, and thermal control layers','Explain flashing as a drainage concept','Recognize common coordination points around windows, roofs, and foundations'],sections:[['Control layers','Durable enclosures manage bulk water, air flow, vapor behavior, and heat flow. The layers need continuity at transitions.'],['Drainage','Water should be directed down and out. Flashing laps and drainage planes are arranged so water does not get trapped behind finishes.'],['Air control','Uncontrolled air leakage moves heat and moisture. Air-sealing details matter at penetrations, top/bottom plates, rim areas, windows, doors, and service openings.'],['Thermal control','Insulation reduces heat flow, but gaps, compression, thermal bridges, and missing alignment with the air barrier can reduce performance.'],['Roof/foundation transitions','Roof penetrations and below-grade foundations are especially sensitive to water management because leakage can damage concealed assemblies.']],keyTerms:['drainage plane','flashing','air barrier','vapor control','thermal bridge','insulation'],check:[{q:'Good flashing generally follows which idea?',options:['Direct water down and out','Trap water behind cladding','Seal only the interior finish','Make every layer horizontal'],answer:0}]});
upsertLecture(construction,'const-l4',{title:'Preview · Sequencing, RFIs & Coordination',week:'Week 4 · Sep 16',duration:'45 min',objectives:['Describe why sequence affects cost and quality','Write a clear RFI question','Identify coordination dependencies among trades'],sections:[['Sequence','Construction is a dependency network. Some work must be inspected, protected, or concealed before later finishes can proceed.'],['RFI','A useful request for information identifies the exact document reference, describes the conflict or missing information, and asks a focused question.'],['Coordination','A framing change can affect electrical, plumbing, HVAC, fire protection, finishes, and schedule. Good coordination looks beyond one trade.']],keyTerms:['sequence','RFI','submittal','coordination','dependency'],check:[{q:'A useful RFI should include:',options:['A vague complaint','Specific drawing/detail references and a focused question','Only a photo with no context','A price increase with no reason'],answer:1}]});

construction.assignments.push(
  {id:'const-orient',title:'Orientation · Site & Drawing Set Check',due:'Aug 26 at 5:00 PM',points:5,group:'Participation',kind:'quiz',completed:true,score:5,submittedAt:'Aug 26 at 4:18 PM',feedback:'Complete.',questions:[{type:'mc',q:'This course simulation is:',options:['An official De Anza course record','An unofficial fictional learning demo','A real Zoom classroom','A transcript'],answer:1}],sampleAnswers:['1']},
  {id:'const-safety',title:'Safety Walkthrough · Hazard Recognition',due:'Aug 30 at 11:59 PM',points:20,group:'Safety',kind:'worksheet',completed:true,score:19,submittedAt:'Aug 30 at 7:36 PM',feedback:'Good hazard recognition. For the ladder example, name the control before the PPE.',instructions:'For each fictional site condition, identify the hazard, who could be exposed, and one control. This is educational only—not site-specific safety training.',questions:[{type:'textarea',q:'1. Unprotected floor opening near a material path: hazard + control.'},{type:'textarea',q:'2. Extension cord crossing a wet access route: hazard + control.'},{type:'textarea',q:'3. Worker using a damaged ladder: hazard + control.'},{type:'textarea',q:'4. Delivery truck backing into a congested area: hazard + control.'}],sampleAnswers:['Fall-through hazard; cover/guard the opening and control access according to the site plan.','Electrical/trip exposure; reroute/protect the cord and keep electrical equipment suitable for the environment.','Fall/equipment failure; remove damaged ladder from service and use proper access equipment.','Struck-by hazard; establish a controlled backing plan/spotter or eliminate backing where possible.']},
  {id:'const-planread',title:'Plan Reading Lab 1 · Plans, Sections & Details',due:'Aug 31 at 11:59 PM',points:25,group:'Plan Reading',kind:'worksheet',completed:true,score:24,submittedAt:'Aug 31 at 10:02 PM',feedback:'Very good. The section-vs-elevation distinction is clear; add sheet/detail references more consistently.',instructions:'Use the fictional mini-set described in the prompt. Answer where you would find each piece of information and explain why.',questions:[{type:'textarea',q:'1. Where would you look for the vertical relationship between floor, ceiling, and roof?'},{type:'textarea',q:'2. Where would you look for a door size repeated across many rooms?'},{type:'textarea',q:'3. A wall type tag points to a detail. Explain the navigation path.'},{type:'textarea',q:'4. Why should written dimensions be preferred over scaling an uncertain screenshot?'}],sampleAnswers:['A building section because it cuts vertically through the assembly.','The door schedule, then confirm special notes/details.','Start at the wall tag on the plan, follow its reference to the wall-type/detail sheet, then read notes/material layers there.','Because screenshots/PDF display sizes can be scaled or distorted; written dimensions are explicit design information.']},
  {id:'const-concretecalc',title:'Concrete Takeoff Lab · Footings & Slab',due:'Sep 6 at 11:59 PM',points:25,group:'Labs & Takeoffs',kind:'worksheet',completed:true,score:24,submittedAt:'Sep 6 at 9:26 PM',feedback:'Math is correct. Good unit conversion. State waste as an estimating assumption rather than a universal rule.',instructions:'Calculate concrete quantities for a fictional project. Show cubic feet, cubic yards, and the effect of an explicitly stated waste factor.',questions:[{type:'text',q:'1. 20 ft × 10 ft slab × 4 in thick = how many cubic feet?'},{type:'text',q:'2. Convert problem 1 to cubic yards.'},{type:'textarea',q:'3. If the estimate applies 5% waste, calculate the order quantity and state the assumption.'},{type:'textarea',q:'4. Explain why reinforcement is not counted simply as “extra concrete.”'}],sampleAnswers:['66.67 ft³','2.47 yd³','2.47 × 1.05 ≈ 2.59 yd³. The 5% is an estimating assumption for this exercise, not a universal rule.','Reinforcing steel is a separate material with its own quantity, placement, detailing, and cost.']},
  {id:'const-takeoff',title:'Week 3 Lab · Room Finish Quantity Takeoff',due:'Sep 12 at 11:59 PM',points:30,group:'Labs & Takeoffs',kind:'worksheet',instructions:'Perform a simplified takeoff for a 12 ft × 15 ft room with 9 ft walls, one 3×7 door, and one 4×4 window. Use the assumptions provided. Show units and deductions.',questions:[{type:'text',q:'1. Floor area in square feet.'},{type:'textarea',q:'2. Gross wall area before openings. Show perimeter × height.'},{type:'textarea',q:'3. Net wall finish area after subtracting the door and window.'},{type:'textarea',q:'4. Baseboard linear feet if the door opening is excluded.'},{type:'textarea',q:'5. Add 10% waste to the net wall finish area and explain why waste factors must be explicitly stated.'}],rubric:[['Geometry & units',10,'Correct lengths/areas and units'],['Opening deductions',6,'Door/window deducted correctly'],['Baseboard',4,'Correct perimeter treatment'],['Waste calculation',5,'Correct extension and stated assumption'],['Organization',5,'Readable takeoff sequence']]},
  {id:'const-cost',title:'Estimating Practice · Extend the Takeoff',due:'Sep 13 at 11:59 PM',points:20,group:'Labs & Takeoffs',kind:'worksheet',instructions:'Use the fictional unit-cost table in the prompt. This is a math exercise only and does not represent real current pricing.',questions:[{type:'textarea',q:'1. If 594 sf of wall finish is priced at $1.85/sf material, calculate material cost.'},{type:'textarea',q:'2. If installation labor is 0.045 hr/sf at $48/hr, calculate labor hours and labor cost.'},{type:'textarea',q:'3. Add the material and labor direct costs.'},{type:'textarea',q:'4. Explain the difference between takeoff quantity and estimate cost.'}]},
  {id:'const-framingquiz',title:'Quiz 2 · Framing Vocabulary & Load Transfer',due:'Sep 11 at 11:59 PM',points:15,group:'Plan Reading',kind:'quiz',questions:[{type:'mc',q:'A header is commonly associated with:',options:['Redirecting load around an opening','Waterproofing a slab','Measuring concrete slump','Electrical grounding'],answer:0},{type:'mc',q:'A joist generally carries:',options:['Floor/ceiling loads to supports','Only paint','Plumbing water directly','Roof flashing'],answer:0},{type:'mc',q:'A construction detail usually provides:',options:['More localized assembly/connection information','Only the project address','A class roster','A final bid price'],answer:0}]}
);
construction.discussions.push(
  {id:'const-disc1',title:'Week 1 Toolbox Talk · What Makes a Site Feel Safe?',due:'Aug 29 at 11:59 PM',points:10,status:'graded',score:10,prompt:'Without pretending to be a safety professional, describe three visible conditions that would make you think a jobsite is being managed carefully. Explain why each matters.',posts:[
    {name:'Sofia Reyes',time:'Aug 28 · 6:44 PM',text:'Clear pedestrian routes, protected openings/edges, and good housekeeping. Those three tell me someone has thought about how people move through the site instead of only where materials go.',replies:[{name:'Marcus Bell',time:'Aug 28 · 7:01 PM',text:'Housekeeping seems basic but it affects trips, access, and whether emergency routes stay usable.'}]},
    {name:'Ethan Cole',time:'Aug 28 · 8:18 PM',text:'I would look for separation between people and moving equipment, especially deliveries. If everyone has to improvise around trucks, that seems like a planning problem.',replies:[{name:'Leah Tran',time:'Aug 28 · 8:52 PM',text:'Agreed. I also notice whether signs/barriers match the actual path instead of being ignored.'}]},
    {name:'Avery Kim',time:'Aug 29 · 3:30 PM',text:'I would look for organized material storage. Stacked material should not block routes or create something unstable that people have to climb around.',replies:[]}
  ]},
  {id:'const-disc2',title:'Week 2 RFI Board · The Drawing Is Unclear',due:'Sep 5 at 11:59 PM',points:10,status:'graded',score:10,prompt:'A floor plan shows a 4-ft opening, but the enlarged detail appears to show 3 ft 8 in. Write a short RFI-style question that identifies the conflict without guessing the answer.',posts:[
    {name:'Noah Brooks',time:'Sep 4 · 6:10 PM',text:'RFI: A2.1 indicates a 4’-0” opening at Room 104, while Detail 5/A6.2 appears to dimension the same opening as 3’-8”. Please confirm the required rough opening dimension and identify which reference governs.',replies:[{name:'Prof. Elena Morales',time:'Sep 4 · 6:42 PM',text:'Fictional instructor note: strong because it cites both references and asks one focused question instead of proposing an undocumented fix.'}]},
    {name:'Mia Johnson',time:'Sep 4 · 7:35 PM',text:'I would attach a marked screenshot showing both callouts so the reviewer does not have to hunt for the conflict.',replies:[{name:'Chris Park',time:'Sep 4 · 7:51 PM',text:'And I would avoid saying “the detail is wrong” because we do not know which one is intended.'}]},
    {name:'Taylor Nguyen',time:'Sep 5 · 10:14 AM',text:'I think the most important part is asking whether 4’-0” is finish opening or rough opening. Sometimes the numbers are describing different things.',replies:[{name:'Sofia Reyes',time:'Sep 5 · 10:44 AM',text:'Good catch—that could resolve the conflict without either drawing being wrong.'}]}
  ]},
  {id:'const-disc3',title:'Week 3 Field Board · Buildability & Coordination',due:'Sep 12 at 11:59 PM',points:10,status:'open',score:null,prompt:'Choose one place where two systems must coordinate—window/wall, roof penetration, pipe through framing, duct above ceiling, slab edge, etc. Explain what information each trade needs and what could go wrong if coordination is late.',posts:[
    {name:'Leah Tran',time:'Sep 8 · 11:22 AM',text:'Window-to-wall coordination needs rough opening size, flashing sequence, sill pan/drainage, fastener locations, insulation/air-seal details, and exterior finish thickness. If those are decided separately, the water-control layers might not connect.',replies:[{name:'Avery Kim',time:'Sep 8 · 12:03 PM',text:'I like that you separated structural fastening from water/air sealing. They overlap at the same opening but solve different problems.'}]},
    {name:'Marcus Bell',time:'Sep 8 · 1:55 PM',text:'A duct crossing under a beam needs elevation information early. If the duct only gets coordinated after framing is installed, somebody may suggest cutting something they should not cut.',replies:[{name:'Noah Brooks',time:'Sep 8 · 2:21 PM',text:'That is where a coordinated section would be more useful than only looking at a floor plan.'}]},
    {name:'Ethan Cole',time:'Sep 8 · 4:06 PM',text:'Roof penetrations seem tricky because structure, roofing, flashing, and mechanical equipment all meet in one spot. The sequence matters because you can make a good detail fail if layers lap the wrong direction.',replies:[{name:'Mia Johnson',time:'Sep 8 · 4:30 PM',text:'And the person sealing it later needs access. Constructability is part of the detail.'},{name:'Sofia Reyes',time:'Sep 8 · 5:02 PM',text:'Maintenance access later is another stakeholder I would add.'}]}
  ]}
);
