function openPracticeLab(id){
  const p=PRACTICE_LABS[id];if(!p)return toast('Practice lab unavailable');
  if(p.type==='choices'){
    const key=`practice:${id}`;const prev=state.quizChecks[key]||{};
    showModal(`<div class="modal-kicker">${escapeHTML(p.course)} · Practice Lab</div><h2>${escapeHTML(p.title)}</h2><p class="lead-copy">${escapeHTML(p.intro)}</p><div class="knowledge-check">${p.items.map((x,i)=>`<fieldset><legend>${i+1}. ${escapeHTML(x.q)}</legend>${x.options.map((o,j)=>`<label><input type="radio" name="pl${i}" value="${j}" ${String(prev.answers?.[i])===String(j)?'checked':''}> ${escapeHTML(o)}</label>`).join('')}</fieldset>`).join('')}<button class="primary-btn" id="scorePractice">Check Answers</button><div id="practiceResult" class="quiz-result"></div></div>`,true);
    document.getElementById('scorePractice').onclick=()=>{const answers=p.items.map((_,i)=>document.querySelector(`input[name="pl${i}"]:checked`)?.value??'');const score=p.items.reduce((n,x,i)=>n+(Number(answers[i])===x.answer?1:0),0);state.quizChecks[key]={answers,score};saveState();document.getElementById('practiceResult').innerHTML=`<strong>${score}/${p.items.length} correct.</strong>${p.items.map((x,i)=>`<p><b>${i+1}.</b> ${Number(answers[i])===x.answer?'✓':'Review:'} ${escapeHTML(x.why)}</p>`).join('')}`;};
  } else if(p.type==='concrete'){
    showModal(`<div class="modal-kicker">CONST 20 · Interactive Lab</div><h2>${escapeHTML(p.title)}</h2><p>${escapeHTML(p.intro)}</p><div class="tool-grid"><label>Length (ft)<input id="cvL" type="number" value="20" min="0"></label><label>Width (ft)<input id="cvW" type="number" value="10" min="0"></label><label>Thickness (in)<input id="cvT" type="number" value="4" min="0"></label><label>Waste (%)<input id="cvWaste" type="number" value="5" min="0"></label></div><button class="primary-btn" id="calcConcrete">Calculate</button><div class="calc-output" id="concreteOutput"></div><div class="study-tip"><strong>Check yourself:</strong> Thickness must be converted from inches to feet before multiplying volume. Divide cubic feet by 27 for cubic yards.</div>`,true);
    const calc=()=>{const L=+document.getElementById('cvL').value,W=+document.getElementById('cvW').value,T=+document.getElementById('cvT').value,w=+document.getElementById('cvWaste').value;if(!(L>0&&W>0&&T>0))return document.getElementById('concreteOutput').textContent='Enter positive dimensions.';const cf=L*W*(T/12),cy=cf/27,order=cy*(1+w/100);document.getElementById('concreteOutput').innerHTML=`<strong>${cf.toFixed(2)} ft³</strong> = <strong>${cy.toFixed(2)} yd³</strong><br>With ${w.toFixed(1)}% exercise waste: <strong>${order.toFixed(2)} yd³</strong>`;};document.getElementById('calcConcrete').onclick=calc;calc();
  } else if(p.type==='room'){
    showModal(`<div class="modal-kicker">CONST 20 · Takeoff Sandbox</div><h2>${escapeHTML(p.title)}</h2><p>${escapeHTML(p.intro)}</p><div class="tool-grid"><label>Room length (ft)<input id="rtL" type="number" value="15" min="0"></label><label>Room width (ft)<input id="rtW" type="number" value="12" min="0"></label><label>Wall height (ft)<input id="rtH" type="number" value="9" min="0"></label><label>Door width (ft)<input id="rtDW" type="number" value="3" min="0"></label><label>Door height (ft)<input id="rtDH" type="number" value="7" min="0"></label><label>Window width (ft)<input id="rtWW" type="number" value="4" min="0"></label><label>Window height (ft)<input id="rtWH" type="number" value="4" min="0"></label><label>Waste (%)<input id="rtWaste" type="number" value="10" min="0"></label></div><button class="primary-btn" id="calcRoom">Update Takeoff</button><div class="takeoff-table" id="roomOutput"></div>`,true);
    const calc=()=>{const L=+document.getElementById('rtL').value,W=+document.getElementById('rtW').value,H=+document.getElementById('rtH').value,dw=+document.getElementById('rtDW').value,dh=+document.getElementById('rtDH').value,ww=+document.getElementById('rtWW').value,wh=+document.getElementById('rtWH').value,waste=+document.getElementById('rtWaste').value;const floor=L*W,per=2*(L+W),gross=per*H,open=dw*dh+ww*wh,net=Math.max(0,gross-open),base=Math.max(0,per-dw),withWaste=net*(1+waste/100);document.getElementById('roomOutput').innerHTML=`<table><tr><th>Item</th><th>Quantity</th></tr><tr><td>Floor area</td><td>${floor.toFixed(1)} sf</td></tr><tr><td>Gross wall area</td><td>${gross.toFixed(1)} sf</td></tr><tr><td>Openings deducted</td><td>${open.toFixed(1)} sf</td></tr><tr><td>Net wall finish</td><td>${net.toFixed(1)} sf</td></tr><tr><td>Baseboard</td><td>${base.toFixed(1)} lf</td></tr><tr><td>Wall finish + ${waste.toFixed(1)}% exercise waste</td><td>${withWaste.toFixed(1)} sf</td></tr></table>`;};document.getElementById('calcRoom').onclick=calc;calc();
  }
  addHistory(p.title,p.course);
}

