const _openLecture=openLecture;
openLecture=function(c,lectureId){
  const l=c.lectures?.[lectureId];if(!l)return _openLecture(c,lectureId);
  const resourcesByLecture={
    'engr-l3':['fbdVideo','openstaxFbd','mitStatics'], 'engr-l3b':['openstaxEquilibrium','openstaxTorque','jeffShear'], 'engr-l4':['jeffTruss'],
    'math-l3':['khanDeriv','mitCalc'], 'phys-l3':['khanFbd','openstaxFbd'],
    'const-l1':['blueprintBasics','blueprintGuide'],'const-l1b':['oshaFalls','oshaVideos'],'const-l2':['practicalConcrete','doeFoundation','doeCapillary'],'const-l2b':['autodeskEstimate'],'const-l3':['doeFraming','jeffTruss'],'const-l3b':['doeInsulation','doeRoofing','doeWaterRoof'], 'const-l4':['doePlumbing','doeHVAC']
  };
  const ids=resourcesByLecture[lectureId]||[];const key=`lecture:${c.id}:${lectureId}`;const previous=state.quizChecks[key]||{};const note=state.drafts[`${key}:note`]||'';
  showModal(`<div class="modal-kicker">${escapeHTML(c.code)} · ${escapeHTML(l.week)} · ${escapeHTML(l.duration)}</div><h2>${escapeHTML(l.title)}</h2><div class="lecture-layout"><main><section class="lecture-objectives"><h3>Learning objectives</h3><ul>${l.objectives.map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ul></section>${l.sections.map((s,i)=>`<section class="lecture-section"><div class="lecture-num">${i+1}</div><div><h3>${escapeHTML(s[0])}</h3><p>${escapeHTML(s[1])}</p></div></section>`).join('')}${lectureId==='engr-l3'?`<section class="beam-tool"><div><h3>Interactive Tool · Simply Supported Beam Reactions</h3><p>Use moment and vertical-force equilibrium for one point load.</p></div><div class="beam-inputs"><label>Beam length L <input id="beamLength" type="number" min="0.1" step="0.1" value="10"><span>ft</span></label><label>Point load P <input id="beamLoad" type="number" min="0" step="10" value="1000"><span>lb</span></label><label>Load position x <input id="beamPosition" type="number" min="0" step="0.1" value="5"><span>ft from A</span></label><button class="primary-btn" id="calcBeam">Calculate reactions</button></div><div class="beam-visual"><div class="beam-line"><i class="support left">▲</i><i class="support right">▲</i><i class="load-arrow" id="loadArrow">↓<small>P</small></i></div><div id="beamResult" class="beam-result">For L = 10 ft, P = 1,000 lb at x = 5 ft: <strong>Ay = 500 lb, By = 500 lb</strong></div></div></section>`:''}<section class="knowledge-check"><h3>Knowledge Check</h3><p>Retry as often as you want. Your latest result is stored locally.</p>${l.check.map((q,i)=>`<fieldset><legend>${i+1}. ${escapeHTML(q.q)}</legend>${q.options.map((o,j)=>`<label><input type="radio" name="kc${i}" value="${j}" ${String(previous.answers?.[i])===String(j)?'checked':''}> ${escapeHTML(o)}</label>`).join('')}</fieldset>`).join('')}<button class="primary-btn" id="submitKnowledgeCheck">Check Answers</button><div id="kcResult" class="quiz-result">${previous.score!=null?`Previous score: ${previous.score}/${l.check.length}`:''}</div></section>${ids.length?`<section class="lecture-resource-block"><h3>Watch / Read Another Explanation</h3><p>These are public external resources, not De Anza course materials.</p><button class="outline-btn" data-resource-bundle="${ids.join(',')}">Open ${ids.length} learning resource${ids.length===1?'':'s'}</button></section>`:''}</main><aside class="lecture-aside"><h4>Key terms</h4>${l.keyTerms.map(k=>`<span class="term-chip">${escapeHTML(k)}</span>`).join('')}<hr><h4>Private study note</h4><textarea id="lectureQuickNote" class="mini-note" placeholder="Write a note…">${escapeHTML(note)}</textarea><button class="outline-btn full" id="saveLectureQuickNote">Save note</button><button class="outline-btn full" id="openFlashcards">Study key terms</button></aside></div>`,true);
  document.getElementById('submitKnowledgeCheck').onclick=()=>{const answers=l.check.map((_,i)=>document.querySelector(`input[name="kc${i}"]:checked`)?.value??'');const score=l.check.reduce((n,q,i)=>n+(Number(answers[i])===q.answer?1:0),0);state.quizChecks[key]={answers,score};saveState();document.getElementById('kcResult').innerHTML=`<strong>${score}/${l.check.length} correct.</strong> ${score===l.check.length?'Mastery check complete.':'Review the related section and retry.'}`;};
  document.getElementById('saveLectureQuickNote').onclick=()=>{state.drafts[`${key}:note`]=document.getElementById('lectureQuickNote').value;saveState();toast('Lecture note saved locally');};
  document.getElementById('openFlashcards').onclick=()=>openFlashcards(c,l);
  document.querySelectorAll('[data-resource-bundle]').forEach(b=>b.onclick=()=>openResources(b.dataset.resourceBundle.split(',')));
  const beamBtn=document.getElementById('calcBeam');if(beamBtn)beamBtn.onclick=()=>{const L=Number(document.getElementById('beamLength').value),P=Number(document.getElementById('beamLoad').value),x=Number(document.getElementById('beamPosition').value),beamResult=document.getElementById('beamResult'),loadArrow=document.getElementById('loadArrow');if(!(L>0)||P<0||x<0||x>L){beamResult.innerHTML='<strong>Check the inputs.</strong> Load position must be between 0 and L.';return;}const By=P*x/L,Ay=P-By;loadArrow.style.left=`${Math.max(0,Math.min(100,(x/L)*100))}%`;beamResult.innerHTML=`ΣM_A: By(${L.toFixed(2)}) − ${P.toFixed(1)}(${x.toFixed(2)}) = 0<br><strong>Ay = ${Ay.toFixed(1)} lb · By = ${By.toFixed(1)} lb</strong>`;};
  addHistory(l.title,c.code);
};

function openFlashcards(c,l){
  const defs={
    'need statement':'A solution-neutral description of the outcome or problem to address.','criterion':'A quality used to compare alternatives.','constraint':'A hard limit a solution must satisfy.','stakeholder':'A person/group affected by or able to affect a project.','trade-off':'A choice where improving one objective can worsen another.','risk':'Potential consequence combined with uncertainty/likelihood.','load path':'The route forces follow through connected components to the ground.','reaction':'A force or moment supplied by a support/contact in the chosen model.','moment':'Rotational effect of a force about a point or axis.','torque':'A rotational effect; in statics often used interchangeably with moment.','truss':'A triangulated system idealized as pin-connected two-force members.','takeoff':'Measurement/listing of quantities from construction documents.','estimate':'Application of cost assumptions to quantities and scope.','RFI':'Request for information used to clarify missing/conflicting project information.','header':'Framing member used to redirect load around an opening in applicable walls.','flashing':'Material/detail arranged to direct water out of an assembly.','air barrier':'A continuous layer intended to control air leakage.','derivative':'Instantaneous rate of change / tangent-line slope where defined.','continuity':'At a point, function value exists, limit exists, and they are equal.','net force':'Vector sum of external forces on the chosen system.','thesis':'Focused arguable claim that guides an essay.'
  };
  const cards=l.keyTerms.map(k=>({term:k,def:defs[k.toLowerCase()]||`Review this term in ${l.title}. Write your own definition and example in your lecture note.`}));let i=0,showDef=false;
  showModal(`<div class="modal-kicker">${escapeHTML(c.code)} · Flashcards</div><h2>${escapeHTML(l.title)}</h2><div class="flashcard" id="flashcard"><small id="flashCount"></small><h3 id="flashTerm"></h3><p id="flashDef"></p></div><div class="flash-controls"><button class="outline-btn" id="flashPrev">← Previous</button><button class="primary-btn" id="flashFlip">Flip</button><button class="outline-btn" id="flashNext">Next →</button></div>`);
  const draw=()=>{const flashCount=document.getElementById('flashCount'),flashTerm=document.getElementById('flashTerm'),flashDef=document.getElementById('flashDef');flashCount.textContent=`${i+1} of ${cards.length}`;flashTerm.textContent=cards[i].term;flashDef.textContent=showDef?cards[i].def:'Click Flip to reveal the definition.';};document.getElementById('flashPrev').onclick=()=>{i=(i-1+cards.length)%cards.length;showDef=false;draw();};document.getElementById('flashNext').onclick=()=>{i=(i+1)%cards.length;showDef=false;draw();};document.getElementById('flashFlip').onclick=()=>{showDef=!showDef;draw();};draw();
}

