function renderStudyCenter(c){
  const el=document.getElementById('courseContent');const pastModules=c.modules.filter(m=>m.state==='complete');const lectures=Object.entries(c.lectures||{});const completed=c.assignments.filter(a=>isSubmitted(c,a));const open=c.assignments.filter(a=>!isSubmitted(c,a));const notes=lectures.filter(([id])=>state.drafts[`lecture:${c.id}:${id}:note`]);
  const resourceIds=[...new Set(c.modules.flatMap(m=>m.items.filter(i=>i.type==='external').flatMap(i=>i.resourceIds||[])))];
  el.innerHTML=`<div class="study-hero"><div><div class="demo-badge">REVIEW & RELEARN</div><h2>${escapeHTML(c.code)} Study Center</h2><p>Go backward without losing context: reopen old lectures, inspect your previous fictional submissions/feedback, retry quizzes, use flashcards, and open the same public learning resources again.</p></div><div class="study-stats"><div><strong>${pastModules.length}</strong><span>completed modules</span></div><div><strong>${completed.length}</strong><span>submitted items</span></div><div><strong>${lectures.length}</strong><span>lectures</span></div><div><strong>${resourceIds.length}</strong><span>external resources</span></div></div></div><div class="study-grid"><section class="study-panel"><h3>Review Previous Modules</h3>${pastModules.map((m,mi)=>`<div class="study-module"><div><strong>${escapeHTML(m.title)}</strong><small>${m.items.length} items</small></div><button class="outline-btn" data-study-action="module" data-id="${c.modules.indexOf(m)}">Open module</button></div>`).join('')||'<p class="muted">No completed modules yet.</p>'}</section><section class="study-panel"><h3>Submitted Work & Feedback</h3>${completed.slice(-8).reverse().map(a=>{const s=submission(c,a);return `<button class="feedback-review" data-study-action="assignment" data-id="${a.id}"><strong>${escapeHTML(a.title)}</strong><span>${s.score!=null?`${s.score}/${a.points}`:'Submitted'}</span><small>${escapeHTML((s.feedback||'Open to review your submission.').slice(0,110))}</small></button>`}).join('')}</section><section class="study-panel"><h3>Lecture Relearn</h3>${lectures.map(([id,l])=>`<button class="feedback-review" data-study-action="lecture" data-id="${id}"><strong>${escapeHTML(l.title)}</strong><span>${state.quizChecks[`lecture:${c.id}:${id}`]?.score!=null?`${state.quizChecks[`lecture:${c.id}:${id}`].score}/${l.check.length} check`:'Review'}</span><small>${escapeHTML(l.objectives[0])}</small></button>`).join('')}</section><section class="study-panel"><h3>Resource Library</h3><p>${resourceIds.length} public resources are linked across this course.</p>${resourceIds.length?`<button class="primary-btn" data-resource-bundle="${resourceIds.join(',')}">Open course resource library</button>`:''}<button class="outline-btn" data-study-action="notes" data-id="notes">Open my saved lecture notes (${notes.length})</button></section></div><section class="study-panel practice-zone"><h3>Active Practice</h3><div class="practice-actions"><button data-study-action="random" data-id="random"><strong>Surprise me with review</strong><small>Open a random lecture, assignment, or practice lab from this course.</small></button><button data-study-action="current" data-id="current"><strong>Continue Week 3</strong><small>Jump back to the current module.</small></button>${c.id==='const20'?`<button data-study-action="practice" data-id="room-takeoff"><strong>Room Takeoff Sandbox</strong><small>Recalculate quantities with different room dimensions.</small></button>`:''}</div></section>`;
  bindCourseControls();
}

function handleStudyAction(action,id){
  const c=currentCourse;
  if(action==='assignment')return openAssignment(c,assignmentById(c,id));
  if(action==='lecture')return openLecture(c,id);
  if(action==='module'){selectCourseTab('modules');setTimeout(()=>{const idx=Number(id);const h=document.querySelector(`[data-module-toggle="${idx}"]`);h?.scrollIntoView({behavior:'smooth',block:'center'});},0);return;}
  if(action==='current'){selectCourseTab('modules');const idx=c.modules.findIndex(m=>m.state==='current');setTimeout(()=>document.querySelector(`[data-module-toggle="${idx}"]`)?.scrollIntoView({behavior:'smooth',block:'center'}),0);return;}
  if(action==='practice')return openPracticeLab(id);
  if(action==='notes'){
    const notes=Object.entries(c.lectures||{}).map(([lid,l])=>({l,n:state.drafts[`lecture:${c.id}:${lid}:note`]})).filter(x=>x.n);showModal(`<div class="modal-kicker">${escapeHTML(c.code)} · Notebook</div><h2>Saved Lecture Notes</h2>${notes.length?notes.map(x=>`<article class="note-card"><strong>${escapeHTML(x.l.title)}</strong><p>${escapeHTML(x.n)}</p></article>`).join(''):'<p>No lecture notes saved yet. Open a lecture and write a private study note.</p>'}`,true);return;
  }
  if(action==='random'){
    const choices=[];for(const [lid] of Object.entries(c.lectures||{}))choices.push(()=>openLecture(c,lid));for(const a of c.assignments)choices.push(()=>openAssignment(c,a));for(const m of c.modules)for(const i of m.items)if(i.type==='practice')choices.push(()=>openPracticeLab(i.practiceId));if(choices.length)choices[Math.floor(Math.random()*choices.length)]();return;
  }
}

