  const host=document.querySelector('.dashboard-aside');if(!host)return;
  let panel=document.getElementById('studySnapshot');if(!panel){panel=document.createElement('section');panel.className='aside-section';panel.id='studySnapshot';host.insertBefore(panel,host.lastElementChild);}
