// ---------- Search extension ----------
openSearch=function(){
  const index=[];for(const c of courses()){index.push({title:`${c.code} - ${c.title}`,sub:c.schedule,action:()=>openCourse(c.id,'home')});index.push({title:`${c.code} Study Center`,sub:'Review & Relearn',action:()=>openCourse(c.id,'study')});for(const a of c.assignments)index.push({title:a.title,sub:`${c.code} · Assignment`,action:()=>{openCourse(c.id,'assignments');setTimeout(()=>openAssignment(courseById(c.id),assignmentById(courseById(c.id),a.id)),0);}});for(const [id,l] of Object.entries(c.lectures||{}))index.push({title:l.title,sub:`${c.code} · Lecture`,action:()=>{openCourse(c.id,'modules');setTimeout(()=>openLecture(courseById(c.id),id),0);}});for(const d of c.discussions||[])index.push({title:d.title,sub:`${c.code} · Discussion`,action:()=>{openCourse(c.id,'discussions');setTimeout(()=>openDiscussion(courseById(c.id),discussionById(courseById(c.id),d.id)),0);}});for(const m of c.modules)for(const i of m.items)if(i.type==='practice'){const p=PRACTICE_LABS[i.practiceId];index.push({title:p.title,sub:`${c.code} · Interactive Lab`,action:()=>{openCourse(c.id,'modules');setTimeout(()=>openPracticeLab(i.practiceId),0);}});}}
  for(const [id,r] of Object.entries(RESOURCES))index.push({title:r.title,sub:`External · ${r.provider}`,action:()=>openResources([id])});
  showModal(`<div class="modal-kicker">Global Search</div><h2>Search courses, lectures, work, labs & resources</h2><input id="globalSearchInput" class="search-input" autofocus placeholder="Try “concrete”, “RFI”, “moments”, “derivative”, “OSHA”…"><div id="globalSearchResults" class="search-results"></div>`);const input=document.getElementById('globalSearchInput'),results=document.getElementById('globalSearchResults');const run=()=>{const q=input.value.trim().toLowerCase();const found=q?index.filter(x=>(x.title+' '+x.sub).toLowerCase().includes(q)).slice(0,18):index.slice(0,10);results.innerHTML=found.map((x,i)=>`<button data-search-index="${i}"><strong>${escapeHTML(x.title)}</strong><small>${escapeHTML(x.sub)}</small></button>`).join('')||'<p class="muted">No matches.</p>';results.querySelectorAll('[data-search-index]').forEach(b=>b.onclick=()=>{const x=found[+b.dataset.searchIndex];closeModal();x.action();});};input.oninput=run;run();setTimeout(()=>input.focus(),0);
};
document.getElementById('searchBtn').onclick=openSearch;

